import java.util.List;
import java.util.ArrayList;
import java.util.Set;
import java.util.HashSet;
import java.util.Collections;
import java.util.Map;
import sailpoint.object.ManagedAttribute.Type;

String SOURCE_ID = "6659e1f4005c400e8ce339362afef7c6";
String DEFAULT_VALUE = "-";

/* Fetch source attribute configuration values from IdentityNow.
   These are defined per-source in the IdentityNow admin UI. */
String identityAttr = idn.getSourceAttributeBySourceId(SOURCE_ID, "identityAttribute");
String entitlementAccAttr = idn.getSourceAttributeBySourceId(SOURCE_ID, "entitlementAccountAttribute");
String parentOrgAttr = idn.getSourceAttributeBySourceId(SOURCE_ID, "parentOrganizationAttribute");
String displayAttr = idn.getSourceAttributeBySourceId(SOURCE_ID, "entitlementDisplayAttribute");
String hierarchySep = idn.getSourceAttributeBySourceId(SOURCE_ID, "hierarchySeparator");

/* Validate that required source attributes are configured. */
if (identityAttr == null || entitlementAccAttr == null || parentOrgAttr == null || displayAttr == null) {
    return DEFAULT_VALUE;
}

/* Retrieve the entitlement value from the identity.
   identityAttr points to the identity attribute that holds the entitlement reference (e.g., "organization"). */
String entitlementValue = null;
if (identity != null) {
    Object val = identity.getAttribute(identityAttr);
    if (val != null) {
        entitlementValue = val.toString();
    }
}

/* If no entitlement value is found on the identity, return the default. */
if (entitlementValue == null || entitlementValue.trim().isEmpty()) {
    return DEFAULT_VALUE;
}

/* Traverse the entitlement hierarchy.
   Each entitlement must expose its parent organization in the attribute named by parentOrganizationAttribute.
   The loop walks up the chain until it reaches an entitlement with no parent (attribute is null/empty). */

/* path: ordered list of entitlement display names from top-level to leaf. */
List path = new ArrayList();
/* visited: cycle detection to prevent infinite loops in case of circular references. */
Set visited = new HashSet();
/* current: the entitlement name currently being processed. */
String current = entitlementValue;
int maxDepth = 20;

while (current != null && !current.trim().isEmpty() && !visited.contains(current) && path.size() < maxDepth) {
    visited.add(current);

    /* Look up the managed attribute details for the current entitlement.
       entitlementAccAttr is the account attribute name that holds the entitlement value on source accounts. */
    sailpoint.rule.ManagedAttributeDetails details = idn.getManagedAttributeDetails(
        SOURCE_ID, entitlementAccAttr, current, Type.Entitlement
    );
    if (details == null) {
        break;
    }

    Map attrs = details.getAttributes();

    /* Read the display name from the configured entitlement attribute (e.g., "name").
       details.getName() returns the account attribute name, not the entitlement display name. */
    String name = null;
    if (attrs != null) {
        Object displayVal = attrs.get(displayAttr);
        if (displayVal != null) {
            name = displayVal.toString();
        }
    }
    if (name == null || name.trim().isEmpty()) {
        name = current;
    }
    path.add(name);

    /* Read the parent organization from the configured entitlement attribute.
       If null or empty, this entitlement has no parent — traversal is complete. */
    String parent = null;
    if (attrs != null) {
        Object parentVal = attrs.get(parentOrgAttr);
        if (parentVal != null) {
            parent = parentVal.toString();
        }
    }
    if (parent == null || parent.trim().isEmpty()) {
        break;
    }
    current = parent;
}

/* If no entitlements were added to the path, return the default. */
if (path.isEmpty()) {
    return DEFAULT_VALUE;
}

/* Reverse the path to get top-down order (root first, leaf last) and join with the hierarchy separator. */
Collections.reverse(path);
StringBuilder result = new StringBuilder();
for (int i = 0; i < path.size(); i++) {
    if (i > 0 && hierarchySep != null) {
        result.append(hierarchySep);
    }
    result.append(path.get(i));
}
return result.toString();
